import urllib.request, json, re, time

# Load fpbase proteins
headers = {'User-Agent':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','Accept':'application/json'}
req = urllib.request.Request("https://www.fpbase.org/api/proteins/", headers=headers)
with urllib.request.urlopen(req, timeout=30) as r:
    proteins = json.load(r)

pdb_ids = set(open('/app/pdb_ids.txt').read().split())

print("=== FPbase proteins with ex_max=505 ===")
for p in proteins:
    for s in p.get('states',[]):
        if s.get('ex_max') == 505:
            print(f"name={p['name']}, slug={p['slug']}, uuid={p['uuid']}, pdb={p.get('pdb',[])}, ex={s.get('ex_max')}, em={s.get('em_max')}")
            print(f"  seq={p.get('seq','')[:80]}...")

print("\n=== FPbase proteins with em_max=610 ===")
for p in proteins:
    for s in p.get('states',[]):
        if s.get('em_max') == 610:
            print(f"name={p['name']}, slug={p['slug']}, uuid={p['uuid']}, pdb={p.get('pdb',[])}, ex={s.get('ex_max')}, em={s.get('em_max')}")
            print(f"  seq={p.get('seq','')[:80]}...")

print("\n=== FPbase proteins referencing our PDB IDs ===")
for p in proteins:
    pbs = p.get('pdb',[])
    if pbs:
        common = set(str(x).upper() for x in pbs) & pdb_ids
        if common:
            states = [(s.get('ex_max'),s.get('em_max')) for s in p.get('states',[])]
            print(f"name={p['name']}, slug={p['slug']}, pdb={pbs}, states={states}")
            print(f"  seq={p.get('seq','')[:100]}...")

# Save fpbase data for later use
with open('/app/fpbase_proteins.json','w') as f:
    json.dump(proteins, f)
print("\nSaved /app/fpbase_proteins.json")
