import urllib.request, re, time

rids = {'heavy_v':'4EEM8H02014', 'light_v':'4EEMAE00014'}
for name, rid in rids.items():
    for attempt in range(3):
        url = f"https://blast.ncbi.nlm.nih.gov/blast/Blast.cgi?CMD=Get&RID={rid}&FORMAT_TYPE=Text&ALIGNMENTS=10"
        try:
            req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            with urllib.request.urlopen(req, timeout=30) as r:
                html = r.read().decode(errors='replace')
            if 'Status=WAITING' in html or 'Status=QUEUED' in html or 'Status=PENDING' in html:
                print(f"{name}: RID={rid} still waiting")
                time.sleep(5)
                continue
            # Print text result or relevant snippet
            # Remove HTML tags for readability
            text = re.sub(r'<[^>]+>', '', html)
            text = re.sub(r'\n\s*\n+', '\n', text)
            print(f"\n=== {name} BLAST result ===")
            # Print portion around hits
            idx = text.find('Sequences producing')
            if idx >= 0:
                print(text[idx:idx+3000])
            else:
                print(text[:3000])
            break
        except Exception as e:
            print(f"{name}: ERROR {e}")
            time.sleep(3)
